function renderMediaResults(body){const items=body.type==='video'?(body.videos||[]):(body.photos||[]);if(!items.length)return '<div class="media-empty">Nenhum resultado encontrado. Tente outra busca.</div>';return items.map(item=>{const image=body.type==='video'?(item.thumb||''):(item.src?.medium||item.src?.small||item.src?.large||'');const proxy=image?'/api/media-image?url='+encodeURIComponent(image):'';const url=item.url||'';const title=item.title||item.alt||item.author||'Mídia Pexels';const author=item.author||'Pexels';return `<article class="media-card"><figure>${image?`<img loading="lazy" src="${esc(proxy)}" alt="${esc(title)}" onerror="this.style.display='none';this.closest('figure').classList.add('media-broken')">`:'<div class="media-empty">Prévia indisponível</div>'}</figure><div class="media-card-body"><b title="${esc(title)}">${esc(title)}</b><small>${esc(author)}</small><div class="media-card-actions"><button class="secondary" data-copy-media-url="${esc(url)}">Copiar link</button><button class="secondary" data-download-media="${esc(proxy)}" data-media-name="${esc(title)}">Baixar</button><button class="secondary" data-save-media-url="${esc(url)}" data-save-media-preview="${esc(proxy)}" data-save-media-title="${esc(title)}" data-save-media-author="${esc(author)}">Salvar</button><a class="secondary" href="${esc(url)}" target="_blank" rel="noreferrer">Abrir</a></div></div></article>`}).join('')}
function renderMediaSaved(){const items=Array.isArray(data.mediaSaved)?data.mediaSaved:[];if(!items.length)return '<div class="media-empty media-empty-small">Você ainda não salvou nenhuma referência.</div>';return items.map((item,index)=>`<article class="media-saved-item"><img loading="lazy" src="${esc(item.preview||'')}" alt="${esc(item.title||'Mídia salva')}" onerror="this.style.display='none'"><div class="media-saved-copy"><b>${esc(item.title||'Mídia salva')}</b><small>${esc(item.author||'Pexels')} • ${esc(item.type||'referência')}</small></div><div class="media-card-actions"><button class="secondary" data-download-saved="${esc(item.preview||'')}" data-media-name="${esc(item.title||'midia')}">Baixar</button><a class="secondary" href="${esc(item.url||'')}" target="_blank" rel="noreferrer">Abrir</a><button class="secondary" data-remove-media="${index}">Remover</button></div></article>`).join('')}
