function downloadMedia(url,title){if(!url)return toast('Prévia indisponível para baixar.');const safe=String(title||'midia').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'midia';const link=document.createElement('a');link.href=url;link.download=`${safe}.jpg`;link.target='_blank';document.body.append(link);link.click();link.remove();toast('Download iniciado')}function renderAnswerFavorites(){const items=Array.isArray(data.answerFavorites)?data.answerFavorites:[];if(!items.length)return '<div class="media-empty media-empty-small">Nenhuma resposta salva ainda.</div>';return items.slice(0,20).map((item,index)=>`<article class="saved-answer"><div><small>${esc(new Date(item.date||Date.now()).toLocaleDateString('pt-BR'))}</small><p>${esc(item.text||'')}</p></div><button class="secondary" data-remove-answer="${index}">Remover</button></article>`).join('')}

const views={
 dashboard(){const done=Object.values(data.tasks).filter(Boolean).length;const progress=Math.min(100,Math.round(done/90*100));return `<section class="ontop-cover"><div class="ontop-word">ONTOP</div><p>CENTRAL PLUS · CONHECIMENTO EM MOVIMENTO</p><div class="cover-actions"><button class="primary" data-page="ai-chat">Conversar com a IA</button><button class="secondary" id="open-learning-home">Abrir aprendizado</button></div></section><section class="welcome-value"><div><p class="eyebrow">COMO A CENTRAL AJUDA</p><h3>Uma área para decidir, criar e executar.</h3><p>Use a IA para clarear o próximo passo, a Jornada para manter constância e a Biblioteca Visual para transformar ideias em materiais.</p></div><button class="secondary" data-page="profile">Personalizar minha IA →</button></section><section class="command-strip"><div><small>PROGRESSO</small><strong>${progress}%</strong><span>${done} de 90 ações</span></div><div><small>TRILHAS</small><strong>14</strong><span>diretórios organizados</span></div><div><small>ACADEMIA</small><strong>1.200</strong><span>prompts em 12 IAs</span></div><div><small>CHAT IA</small><strong>20</strong><span>perguntas por dia</span></div></section><div class="hub-heading"><p class="eyebrow">ESCOLHA UMA ÁREA</p><h3>Tudo organizado em poucos caminhos.</h3></div><section class="main-hub"><button data-page="ai-chat"><i>01</i><span><b>Chat IA</b><small>Pergunte sobre produto, oferta, conteúdo e projetos</small></span><em>→</em></button><button id="home-learning"><i>02</i><span><b>Aprender</b><small>14 trilhas com aulas e progresso</small></span><em>→</em></button><button id="home-ai"><i>03</i><span><b>Academia de IAs</b><small>12 diretórios e 1.200 prompts</small></span><em>→</em></button><button data-page="management"><i>04</i><span><b>Organizar</b><small>Clientes, projetos, finanças e arquivos</small></span><em>→</em></button><button data-page="journey"><i>05</i><span><b>Jornada de 90 dias</b><small>Nove fases progressivas de execução</small></span><em>→</em></button></section><section class="dashboard-insights"><div class="insight-card" data-page="journey" tabindex="0" role="button"><small>PRÓXIMA AÇÃO</small><strong>${done<90?`Dia ${done+1} da jornada`:'Revisar seu progresso'}</strong><p>Escolha uma ação pequena e concluível para manter seu ritmo.</p></div><div class="insight-card" data-page="management" tabindex="0" role="button"><small>ESPAÇO DE TRABALHO</small><strong>${data.projects.length} projetos</strong><p>Organize ideias, clientes e próximos passos em um só lugar.</p></div><div class="insight-card" data-page="media" tabindex="0" role="button"><small>BIBLIOTECA VISUAL</small><strong>Buscar mídia</strong><p>Encontre referências para posts, capas e materiais.</p></div></section>`},
 workspace(){return `<section class="section-intro"><p class="eyebrow">CENTRO DE FERRAMENTAS</p><h2>Crie, comunique e execute.</h2><p>Os recursos ficam dentro desta página, sem ocupar a barra lateral.</p><div class="tool-legend"><span class="tool-kind uses-ai">IA • USA PERGUNTAS</span><small>Gera uma resposta nova e consome 1 das 20 perguntas diárias.</small><span class="tool-kind normal-tool">NORMAL • SEM IA</span><small>Calcula, registra ou organiza sem consumir perguntas.</small></div></section><section class="portal-grid">${[['ai-chat','✦','Chat IA','Faça perguntas livres — limite de 20 por dia'],['ideas','✦','Laboratório de ideias','Gerar, validar e comparar'],['product','▦','Construtor de produto','Estrutura, módulos e bônus'],['offer','◫','Oferta e página','Valor, preço e conversão'],['content','▶','Conteúdo e anúncios','Vídeos, carrosséis e campanhas'],['messages','✉','Mensagens e e-mails','Propostas e comunicação'],['prompts','⌘','Biblioteca de prompts','300 comandos por assunto'],['journey','↗','Jornada de 90 dias','Plano progressivo'],['goals','◆','Metas e conquistas','Acompanhe sua evolução']].map(x=>`<button data-page="${x[0]}"><i>${x[1]}</i><span><b>${x[2]}</b><small>${x[3]}</small></span><em>→</em></button>`).join('')}<button data-tool="pdf"><i>▤</i><span><b>Gerador de PDF</b><small>Transforme uma ideia ou resposta em material baixável</small></span><em>→</em></button></section>`},
 'ai-chat'(){ensureChatThread();return `<section class="ai-directory clean-chat"><aside class="chat-history"><button class="primary new-chat" id="new-chat">＋ Nova conversa</button><p>CONVERSAS</p><div>${data.conversations.map(thread=>`<button class="chat-history-item ${thread.id===data.activeChatId?'active':''}" data-chat-id="${esc(thread.id)}">${esc(thread.title||'Nova conversa')}</button>`).join('')||'<small>Nenhuma conversa anterior.</small>'}</div></aside><div class="chat-main"><div class="clean-chat-head"><img class="ontop-chat-logo" src="/assets-ontop-mark.svg?v=2" alt="OnTop"><div class="compact-quota"><strong id="ai-remaining">20</strong><span>perguntas disponíveis hoje</span></div></div><div class="ai-context-bar"><div class="field"><label for="ai-niche">Modo de atendimento</label><select id="ai-niche"><option value="Negócios e produtos digitais" ${data.settings.niche==='Negócios e produtos digitais'?'selected':''}>Negócios e produtos digitais</option><option value="Vendas e atendimento" ${data.settings.niche==='Vendas e atendimento'?'selected':''}>Vendas e atendimento</option><option value="Afiliados e conteúdo" ${data.settings.niche==='Afiliados e conteúdo'?'selected':''}>Afiliados e conteúdo</option><option value="Organização financeira" ${data.settings.niche==='Organização financeira'?'selected':''}>Organização financeira</option><option value="Estudos e carreira" ${data.settings.niche==='Estudos e carreira'?'selected':''}>Estudos e carreira</option></select></div><div class="quick-prompts"><small>Comece por um exemplo</small><div><button class="secondary" data-quick-prompt="Crie um plano de ação para organizar meu próximo passo.">Plano de ação</button><button class="secondary" data-quick-prompt="Analise esta ideia e mostre como validar com segurança.">Validar ideia</button><button class="secondary" data-quick-prompt="Crie uma resposta profissional para um cliente interessado.">Responder cliente</button></div></div></div><div class="chat-shell"><div class="chat-messages" id="chat-messages" role="log" aria-live="polite">${renderChatMessages()}</div><form class="chat-composer" id="ai-chat-form"><label class="sr-only" for="ai-chat-input">Digite sua pergunta para a IA</label><textarea id="ai-chat-input" aria-label="Digite sua pergunta para a IA" minlength="10" maxlength="1200" rows="3" placeholder="Pergunte alguma coisa..."></textarea><div><small id="ai-chat-help">Mínimo de 10 letras</small><button class="primary" id="ai-chat-send" disabled>Enviar</button></div></form><div class="chat-tools"><button class="secondary" id="chat-export">Exportar</button><button class="secondary" id="chat-import">Restaurar</button><button class="secondary" id="chat-clear">Limpar conversa atual</button><input class="sr-only" id="chat-file" type="file" accept="application/json"></div></div></div></section>`},
 management(){return `<section class="section-intro"><p class="eyebrow">CENTRO DE ORGANIZAÇÃO</p><h2>Controle sem bagunça.</h2><p>Gestão, registros e exportações reunidos em uma única área.</p></section><section class="portal-grid">${[['crm','♙','Clientes e CRM','Contatos e etapas'],['projects','▣','Projetos e processos','Prazos e próximas ações'],['finance','◒','Finanças','Entradas, saídas e margem'],['funnel','⌁','Funil e métricas','Conversão e indicadores'],['notes','✎','Notas','Aprendizados importantes'],['files','↓','Arquivos e backups','JSON e planilhas CSV'],['updates','●','Novidades','Atualizações da Central']].map(x=>`<button data-page="${x[0]}"><i>${x[1]}</i><span><b>${x[2]}</b><small>${x[3]}</small></span><em>→</em></button>`).join('')}<button data-tool="pdf"><i>▤</i><span><b>Gerador de PDF</b><small>Crie um material profissional para baixar</small></span><em>→</em></button></section>`},
  profile(){const niche=data.settings.niche||'Negócios e produtos digitais';const answers=Array.isArray(data.answerFavorites)?data.answerFavorites.length:0;const media=Array.isArray(data.mediaSaved)?data.mediaSaved.length:0;return `<section class="profile-page"><div class="page-intro"><p class="eyebrow">SUA CENTRAL</p><h2>Meu perfil e preferências.</h2><p>Personalize o modo da IA, acompanhe seu uso e encontre o que você salvou.</p></div><div class="profile-grid"><section class="card profile-card"><div class="profile-avatar">${(state.access?.name||'A').charAt(0).toUpperCase()}</div><h3>${esc(state.access?.name||'Membro OnTop')}</h3><p class="muted">Acesso individual protegido</p><div class="profile-status"><span></span> Plano ativo</div><dl><div><dt>E-mail</dt><dd>${esc(state.access?.email||'Protegido')}</dd></div><div><dt>Respostas salvas</dt><dd>${answers}</dd></div><div><dt>Referências de mídia</dt><dd>${media}</dd></div></dl></section><section class="card profile-card"><p class="eyebrow">PREFERÊNCIA DA IA</p><h3>Como você quer receber ajuda?</h3><div class="field"><label for="profile-niche">Modo principal</label><select id="profile-niche"><option ${niche==='Negócios e produtos digitais'?'selected':''}>Negócios e produtos digitais</option><option ${niche==='Vendas e atendimento'?'selected':''}>Vendas e atendimento</option><option ${niche==='Afiliados e conteúdo'?'selected':''}>Afiliados e conteúdo</option><option ${niche==='Organização financeira'?'selected':''}>Organização financeira</option><option ${niche==='Estudos e carreira'?'selected':''}>Estudos e carreira</option></select></div><button class="primary" id="save-profile">Salvar preferência</button><div class="quota-panel"><div><small>USO DA IA HOJE</small><strong id="profile-remaining">Verificando...</strong></div><p>O limite é renovado automaticamente no próximo dia.</p></div></section></div><section class="card saved-answers-card"><div class="media-collection-head"><div><p class="eyebrow">RESPOSTAS SALVAS</p><h3>Seu material reutilizável</h3></div><button class="secondary" data-page="ai-chat">Abrir IA</button></div><div class="saved-answers-list">${renderAnswerFavorites()}</div></section></section>`}, media(){return `<section class="media-page"><div class="page-intro"><div><p class="eyebrow">BIBLIOTECA VISUAL</p><h2>Encontre mídia para suas ideias.</h2><p>Pesquise fotos e vídeos livres no Pexels para capas, posts, apresentações e produtos. Salve referências e baixe as prévias quando precisar.</p></div><div class="insight-card"><small>DISPONÍVEL HOJE</small><strong id="media-remaining">30 buscas</strong><p>Limite diário por sessão.</p></div></div><section class="card media-search"><form id="media-form"><div class="field"><label for="media-query">O que você quer encontrar?</label><input id="media-query" minlength="3" autocomplete="off" placeholder="Ex.: escritório moderno, rotina saudável, empreendedorismo"></div><div class="field"><label for="media-type">Tipo</label><select id="media-type"><option value="photo">Fotos</option><option value="video">Vídeos</option></select></div><button class="primary" type="submit">Pesquisar mídia</button></form><div class="media-meta"><span>Fonte: Pexels</span><span>•</span><span>Links de origem mantidos</span></div></section><section id="media-results" class="media-results" aria-live="polite"><div class="media-empty">Digite um tema e pesquise para começar.</div></section><section class="card media-collection"><div class="media-collection-head"><div><p class="eyebrow">MINHAS REFERÊNCIAS</p><h3>Salvos e pesquisas recentes</h3></div><button class="secondary" id="clear-media-saved">Limpar salvos</button></div><div id="media-saved-list" class="media-saved-list">${renderMediaSaved()}</div><div class="media-history-wrap"><small>Pesquisas recentes</small><div id="media-history-list" class="media-history-list">${renderMediaHistory()}</div></div></section></section>`},
 legal(){return `<section class="legal-page"><div class="page-intro"><p class="eyebrow">TRANSPARÊNCIA</p><h2>Termos e privacidade.</h2><p>Informações simples sobre uso responsável da Central OnTop.</p></div><div class="legal-grid"><article class="card"><h3>Uso da plataforma</h3><p>O OnTop oferece organização, ideias e respostas assistidas por inteligência artificial. Revise qualquer conteúdo antes de usar, publicar ou enviar a outra pessoa.</p><p>A IA pode cometer erros. Não use as respostas como aconselhamento médico, jurídico ou financeiro personalizado.</p></article><article class="card"><h3>Dados e privacidade</h3><p>O acesso é individual. O site salva preferências, progresso, conversas e itens favoritos para manter sua experiência sincronizada.</p><p>Não compartilhe seu código de acesso. Para solicitar correção ou remoção de dados, use o canal de suporte informado na sua compra.</p></article><article class="card"><h3>Mídias do Pexels</h3><p>As referências visuais são carregadas do Pexels. Confira a licença e as condições do autor antes de usar comercialmente. O OnTop não reivindica autoria dessas imagens.</p></article><article class="card"><h3>Resultados e responsabilidades</h3><p>Organização e ferramentas não garantem vendas, renda ou qualquer resultado financeiro. Resultados dependem de contexto, execução, mercado e decisões do usuário.</p></article></div></section>`},journey(){const done=Object.values(data.tasks).filter(Boolean).length;return `<section class="hero"><p class="eyebrow">PLANO INTERATIVO</p><h3>Jornada de <span class="gold">90 dias</span></h3><p>Cada dia possui uma ação concreta. Marque somente quando salvar o entregável.</p><div class="progress"><i style="width:${done/90*100}%"></i></div></section><div class="grid"><div class="card full"><div class="action-row"><button class="secondary" id="export-plan">Exportar progresso CSV</button><button class="secondary" id="reset-filter">Mostrar todos</button></div><div class="list" id="journey-list">${days90.map(d=>`<label class="list-item ${data.tasks[d.day]?'done':''}"><input type="checkbox" data-day="${d.day}" ${data.tasks[d.day]?'checked':''}><span><b>Dia ${d.day}</b> — ${d.task}</span><em class="badge gold">${d.phase}</em></label>`).join('')}</div></div></div>`},
 diagnostic(){return `<div class="grid">${formResult('Diagnóstico: qual caminho priorizar?',[{id:'need',label:'O que você mais precisa agora?',ph:'Gerar caixa, criar escala ou organizar finanças?'},{id:'resource',label:'Seu principal recurso atual',ph:'Tempo, habilidade, conhecimento ou renda estável'},{id:'problem',label:'Maior obstáculo',ph:'Clientes, produto, divulgação, organização...'},{id:'hours',label:'Horas disponíveis por semana',type:'number',value:'5'}],'Gerar diagnóstico')}<div class="card full"><h3>Três caminhos OnTop</h3><div class="tool-grid">${tool('♙','Serviços','Gerar caixa resolvendo problemas específicos.','path-service')}${tool('▦','Produtos','Transformar conhecimento em uma entrega reutilizável.','path-product')}${tool('◒','Patrimônio','Organizar excedente, objetivos, prazo e risco.','path-assets')}</div></div></div>`},
 goals(){return `<div class="grid"><div class="card full"><h3>Metas ativas</h3><div class="form-grid"><div class="field"><label>Nova meta</label><input id="goal-name" placeholder="Ex.: validar minha primeira oferta"></div><div class="field"><label>Prazo</label><input id="goal-date" type="date"></div></div><button class="primary" id="add-goal" style="margin-top:12px;padding:12px 18px">Adicionar meta</button><div class="list" style="margin-top:18px">${data.goals.length?data.goals.map((g,i)=>`<div class="list-item"><span><b>${esc(g.name)}</b><small> • ${esc(g.date||'sem prazo')}</small></span><button class="secondary" data-delete-goal="${i}">Concluir</button></div>`).join(''):'<p>Nenhuma meta cadastrada.</p>'}</div></div><div class="card half"><h3>Conquistas</h3><div class="list"><div class="list-item"><span>🏁 Primeiro acesso</span><b class="badge green">Conquistado</b></div><div class="list-item"><span>⚡ 7 tarefas concluídas</span><b class="badge ${Object.values(data.tasks).filter(Boolean).length>=7?'green':''}">${Object.values(data.tasks).filter(Boolean).length>=7?'Conquistado':'Bloqueado'}</b></div><div class="list-item"><span>💼 Primeiro cliente</span><b class="badge ${data.clients.length?'green':''}">${data.clients.length?'Conquistado':'Bloqueado'}</b></div></div></div><div class="card half"><h3>Certificado</h3><p>Disponível quando as 90 tarefas forem concluídas. O certificado confirma participação no plano, não resultado financeiro.</p><button class="secondary" id="certificate" ${Object.values(data.tasks).filter(Boolean).length<90?'disabled':''}>Gerar certificado</button></div></div>`},
 ideas(){return `<div class="grid"><div class="card full"><h3>Laboratório de ideias</h3><p>Crie, compare e valide antes de produzir tudo.</p><div class="tool-grid">${tool('✦','Gerador de ideias','Combine público, problema e formato.','idea-generator')}${tool('◎','Validador com pontuação','Avalie urgência, acesso, habilidade e custo.','validator')}${tool('⇄','Comparador de ideias','Compare até três opções lado a lado.','compare')}${tool('☆','Favoritos','Consulte ideias e textos salvos.','favorites')}</div></div><div class="card full"><h3>Ideias salvas</h3><div class="list">${data.ideas.length?data.ideas.map((x,i)=>`<div class="list-item"><span><b>${esc(x.name)}</b><small> • ${esc(x.audience)}</small></span><button class="secondary" data-delete-idea="${i}">Excluir</button></div>`).join(''):'<p>Nenhuma ideia salva.</p>'}</div></div></div>`},
 product(){return `<div class="grid"><div class="card full"><h3>Construtor de produto</h3><div class="tool-grid">${tool('▦','Produto mínimo útil','Defina uma pequena transformação completa.','mvp')}${tool('☷','Módulos e capítulos','Monte a estrutura de e-book ou curso.','modules')}${tool('▤','Gerador de PDF','Transforme uma resposta em material baixável.','pdf')}${tool('＋','Bônus coerentes','Crie bônus ligados ao problema principal.','bonuses')}${tool('✓','Checklist de qualidade','Revise conteúdo, arquivos, links e promessas.','quality')}</div></div></div>`},
 offer(){return `<div class="grid"><div class="card full"><h3>Oferta, preço e conversão</h3><div class="tool-grid">${tool('◫','Construtor de oferta','Público, problema, entrega, prova, limite e CTA.','offer-builder')}${tool('▤','Página de vendas','Estrutura completa em blocos.','sales-page')}${tool('＋','Plano Plus','Organize uma única oferta completa e coerente.','plans')}${tool('◒','Preço e margem','Calcule custos, horas, taxas e margem.','pricing')}${tool('?','FAQ e objeções','Crie respostas claras e responsáveis.','faq')}</div></div></div>`},
 content(){return `<div class="grid"><div class="card full"><h3>Estúdio de conteúdo</h3><div class="tool-grid">${tool('▶','Roteiro de Reel','Gancho, cenas, fala, prova e CTA.','reel')}${tool('▥','Carrossel','Estrutura de 7 telas.','carousel')}${tool('▦','Calendário 30/90 dias','Plano de conteúdo personalizável.','calendar')}${tool('⚡','Anúncio','Texto curto para anúncio sem promessas.','ad')}${tool('#','Ganchos','Gere 10 aberturas para vídeo.','hooks')}</div></div></div>`},
 messages(){return `<div class="grid"><div class="card full"><h3>Comunicação comercial</h3><div class="tool-grid">${tool('✉','E-mail de divulgação','Assunto, prévia, corpo e CTA.','email')}${tool('◉','WhatsApp','Contato, follow-up, entrega ou reativação.','whatsapp')}${tool('▤','Proposta comercial','Escopo, prazo, limites e investimento.','proposal')}${tool('☑','Briefing de cliente','Perguntas para começar sem retrabalho.','briefing')}${tool('⚖','Contrato orientativo','Roteiro de cláusulas para revisão profissional.','contract')}</div></div></div>`},
 prompts(){const categories=[...new Set(prompts.map(item=>item.cat))];return `<div class="grid"><div class="card full"><h3>300 prompts organizados por assunto</h3><p>Escolha uma categoria abaixo. Todos os prompts já estão separados e disponíveis, sem necessidade de pesquisa.</p>${categories.map(category=>`<details class="guide-lesson" style="margin-top:12px"><summary><span class="guide-lesson-number">✦</span><span><strong>${esc(category)}</strong><small>30 prompts prontos para usar</small></span><span class="guide-lesson-state">+</span></summary><div class="list" style="padding:15px">${renderPrompts(prompts.filter(item=>item.cat===category))}</div></details>`).join('')}</div></div>`},
 crm(){return `<div class="grid"><div class="card full"><h3>Clientes e CRM</h3><div class="form-grid"><div class="field"><label>Cliente</label><input id="client-name"></div><div class="field"><label>Contato</label><input id="client-contact"></div><div class="field"><label>Serviço/produto</label><input id="client-product"></div><div class="field"><label>Etapa</label><select id="client-stage"><option>Contato</option><option>Conversa</option><option>Proposta</option><option>Venda</option><option>Pós-venda</option></select></div></div><button class="primary" id="add-client" style="margin-top:12px;padding:12px 18px">Adicionar cliente</button><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>CLIENTE</th><th>CONTATO</th><th>ENTREGA</th><th>ETAPA</th><th>AÇÃO</th></tr></thead><tbody>${data.clients.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${esc(x.contact)}</td><td>${esc(x.product)}</td><td><span class="badge gold">${esc(x.stage)}</span></td><td><button class="secondary" data-delete-client="${i}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhum cliente cadastrado.</td></tr>'}</tbody></table></div></div></div>`},
 projects(){return `<div class="grid"><div class="card full"><h3>Projetos e processos</h3><p>Registre apenas o projeto, o prazo e a próxima ação. Para criar procedimentos, briefings ou auditorias, use o diretório IA.</p><div class="form-grid"><div class="field"><label>Projeto</label><input id="project-name"></div><div class="field"><label>Prazo</label><input id="project-date" type="date"></div><div class="field full"><label>Próxima ação</label><input id="project-next"></div></div><button class="primary" id="add-project" style="margin-top:12px;padding:12px 18px">Adicionar projeto</button><div class="list" style="margin-top:18px">${data.projects.map((x,i)=>`<div class="list-item"><span><b>${esc(x.name)}</b><small> • ${esc(x.next)} • ${esc(x.date||'sem prazo')}</small></span><button class="secondary" data-delete-project="${i}">Concluir</button></div>`).join('')||'<p>Nenhum projeto ativo.</p>'}</div></div></div>`},
 finance(){const ins=data.finance.filter(x=>x.type==='entrada').reduce((a,b)=>a+Number(b.value),0),outs=data.finance.filter(x=>x.type==='saida').reduce((a,b)=>a+Number(b.value),0);return `<div class="grid">${metric('Entradas',money(ins),'valores registrados')}${metric('Saídas',money(outs),'custos e despesas')}${metric('Saldo',money(ins-outs),'não representa lucro tributável')}<div class="card full"><h3>Novo lançamento</h3><p>Use esta página somente para registrar valores. Para análises e cenários, converse com a IA.</p><div class="form-grid"><div class="field"><label>Descrição</label><input id="fin-desc"></div><div class="field"><label>Valor</label><input id="fin-value" type="number" step="0.01"></div><div class="field"><label>Tipo</label><select id="fin-type"><option value="entrada">Entrada</option><option value="saida">Saída</option></select></div><div class="field"><label>Categoria</label><input id="fin-cat" placeholder="Venda, ferramenta, anúncio..."></div></div><button class="primary" id="add-fin" style="margin-top:12px;padding:12px 18px">Registrar</button></div></div>`},
 funnel(){const stages=['Contato','Conversa','Proposta','Venda','Pós-venda'];const counts=stages.map(s=>data.clients.filter(x=>x.stage===s).length);const max=Math.max(1,...counts);return `<div class="grid"><div class="card wide"><h3>Funil de clientes</h3><div class="bar-chart">${stages.map((s,i)=>`<div style="height:${Math.max(5,counts[i]/max*100)}%"><b>${counts[i]}</b><span>${s}</span></div>`).join('')}</div></div><div class="card"><h3>Conversão</h3><div class="stat gold">${counts[0]?Math.round(counts[3]/counts[0]*100):0}%</div><p>Vendas divididas por contatos cadastrados. Para diagnóstico e planejamento, use o diretório IA.</p></div></div>`},
 notes(){return `<div class="grid"><div class="card full"><h3>Notas e aprendizados</h3><div class="form-grid"><div class="field"><label>Título</label><input id="note-title"></div><div class="field full"><label>Anotação</label><textarea id="note-body" rows="5"></textarea></div></div><button class="primary" id="add-note" style="margin-top:12px;padding:12px 18px">Salvar anotação</button><div class="list" style="margin-top:18px">${data.notes.map((x,i)=>`<div class="list-item"><span><b>${esc(x.title)}</b><small> • ${esc(x.body)}</small></span><button class="secondary" data-delete-note="${i}">Excluir</button></div>`).join('')||'<p>Nenhuma anotação.</p>'}</div></div></div>`},
 files(){return `<div class="grid"><div class="card full"><h3>Arquivos e backups</h3><p>Exporte seus próprios registros. O backup não inclui a senha nem o código de acesso.</p><div class="tool-grid">${tool('⬇','Backup completo','Baixe seus dados em JSON.','backup')}${tool('▥','Clientes CSV','Exporte seu CRM.','clients-csv')}${tool('◒','Financeiro CSV','Exporte receitas e despesas.','finance-csv')}${tool('✓','Progresso CSV','Exporte os 90 dias.','progress-csv')}${tool('↥','Restaurar backup','Importe um JSON criado aqui.','restore')}</div></div><div class="card full"><h3>Instalar no celular</h3><p>Use “Instalar aplicativo” no topo ou “Adicionar à tela inicial” no navegador. A Central funciona como aplicativo e mantém seus dados no aparelho.</p></div></div>`},
 updates(){return `<div class="grid"><div class="card wide"><h3>Novidades OnTop Plus</h3><div id="announcements"><div class="notice">A Central Plus foi criada com ferramentas interativas, plano de 90 dias, geradores, CRM, finanças e exportações.</div></div></div><div class="card"><h3>Suporte técnico</h3><p>Ao relatar um erro, informe aparelho, navegador, página e envie uma imagem. Nunca envie seu código em comentários públicos.</p><button class="secondary" data-tool="support">Abrir checklist</button></div><div class="card full"><h3>Avisos importantes</h3><p>Este conteúdo é educacional e não substitui aconselhamento financeiro, jurídico, contábil ou de investimento. Não existe garantia de renda, prazo ou enriquecimento.</p></div></div>`}
};

function renderPrompts(list){return list.map(p=>`<div class="list-item"><span><b>#${p.id} • ${p.cat}</b><small> — ${esc(p.text)}</small></span><button class="secondary" data-copy-text="${esc(p.text)}">Copiar</button></div>`).join('')||'<p>Nenhum prompt encontrado.</p>'}
const generators={
 'idea-generator':['Gerador de ideias',[['Público','aud'],['Problema frequente','prob'],['Habilidade ou conhecimento','skill']],v=>`IDEIAS PARA ${v.aud.toUpperCase()}\n\n1. Checklist para ${v.prob}\n2. Planilha de controle ligada a ${v.prob}\n3. Guia prático usando ${v.skill}\n4. Kit de modelos editáveis\n5. Mini treinamento com uma tarefa completa\n\nValidação: converse com cinco pessoas, mostre apenas a estrutura e registre objeções antes de produzir tudo.`],
 'validator':['Validador de ideia',[['Nome da ideia','name'],['Público acessível','aud'],['Problema que resolve','prob'],['Como você entregará','delivery']],v=>{const score=[v.aud,v.prob,v.delivery].filter(x=>x.length>8).length*25+20;return `PONTUAÇÃO INICIAL: ${Math.min(95,score)}/100\n\nPúblico: ${v.aud}\nProblema: ${v.prob}\nEntrega: ${v.delivery}\n\nPróximo teste: faça cinco entrevistas abertas, mostre uma amostra pequena e confirme se a pessoa entende a utilidade. Pontuação não prevê vendas.`}],
 'offer-builder':['Construtor de oferta',[['Público','aud'],['Problema','prob'],['Entregas','delivery'],['Preço','price']],v=>`PARA QUEM: ${v.aud}\nPROBLEMA: ${v.prob}\nENTREGA: ${v.delivery}\nINVESTIMENTO: ${v.price}\nLIMITES: não inclui resultados garantidos; exige personalização e execução.\nPROVA RESPONSÁVEL: mostre páginas, arquivos e processo reais.\nCTA: veja a demonstração e escolha se esta entrega combina com seu momento.`],
 'pricing':['Calculadora de preço',[['Horas estimadas','hours','number'],['Valor desejado por hora','hourValue','number'],['Custos diretos','cost','number'],['Taxas (%)','fee','number']],v=>{const base=+v.hours*+v.hourValue + +v.cost;const price=base/(1-(+v.fee/100||0));return `Custo de tempo: ${money(+v.hours*+v.hourValue)}\nCustos diretos: ${money(v.cost)}\nPreço mínimo antes de margem adicional: ${money(price)}\n\nInclua impostos, suporte, revisões, aquisição de cliente e risco antes de definir o preço final.`}],
 'reel':['Roteiro de Reel',[['Tema','topic'],['Público','aud'],['Objetivo','goal'],['CTA','cta']],v=>`0–3s — GANCHO: “${v.aud}, pare um segundo: ${v.topic} pode estar sendo feito do jeito mais difícil.”\n3–12s — CONTEXTO: mostre uma situação real sem inventar números.\n12–30s — VALOR: explique três passos ligados a ${v.goal}.\n30–40s — DEMONSTRAÇÃO: mostre tela, arquivo ou processo.\n40–48s — CUIDADO: resultado depende de contexto e execução.\n48–55s — CTA: ${v.cta}.`],
 'mvp':['Produto mínimo útil',[['Público','aud'],['Tarefa que precisa concluir','task'],['Formato preferido','format']],v=>`PRODUTO MÍNIMO\nPúblico: ${v.aud}\nTarefa completa: ${v.task}\nFormato: ${v.format}\n\nEstrutura: 1) instrução curta; 2) exemplo preenchido; 3) arquivo editável; 4) checklist de conclusão; 5) limites e FAQ.\nTeste com três pessoas antes de ampliar.`],
 'modules':['Módulos e capítulos',[['Tema','topic'],['Resultado realista','goal'],['Quantidade de módulos','count','number']],v=>Array.from({length:Math.max(3,Math.min(12,+v.count||5))},(_,i)=>`Módulo ${i+1}: ${['Diagnóstico','Fundamentos','Preparação','Execução','Exemplo','Revisão','Métricas','Próximo ciclo'][i%8]} de ${v.topic}\n• Objetivo\n• Passo a passo\n• Exemplo\n• Atividade\n• Entregável`).join('\n\n')],
 'bonuses':['Bônus coerentes',[['Produto principal','product'],['Principal dificuldade','prob']],v=>`BÔNUS 1 — Checklist para evitar erros em ${v.prob}\nBÔNUS 2 — Modelo editável ligado a ${v.product}\nBÔNUS 3 — Exemplo preenchido\nBÔNUS 4 — Plano de aplicação de 7 dias\n\nMantenha somente bônus que reduzem esforço ou erro na transformação principal.`],
 'sales-page':['Página de vendas',[['Produto','product'],['Público','aud'],['Problema','prob'],['Conteúdo incluído','inside']],v=>`TÍTULO: ${v.product} para ${v.aud}\nSUBTÍTULO: uma estrutura prática para ${v.prob}, com aplicação passo a passo.\n\nSITUAÇÃO ATUAL\nDescreva o problema usando as palavras reais do público.\n\nCOMO FUNCIONA\nExplique o mecanismo sem “segredo” inventado.\n\nVOCÊ RECEBE\n${v.inside}\n\nPARA QUEM É / NÃO É\nInclua esforço necessário e limitações.\n\nDEMONSTRAÇÃO\nMostre os arquivos reais.\n\nFAQ, PREÇO, ACESSO E CTA\nRevise links, compatibilidade, suporte e políticas antes de publicar.`],
 'plans':['Criador de três planos',[['Produto','product'],['Entrega essencial','base'],['Entrega avançada','advanced']],v=>`INÍCIO — orientação\n• ${v.base}\n• Primeiro passo e checklist\n\nPREMIUM — execução\n• Tudo do Início\n• Modelos, calendário e acompanhamento\n\nPLUS — sistema completo\n• Tudo do Premium\n• ${v.advanced}\n• Ferramentas interativas e atualizações\n\nAs diferenças precisam existir de verdade antes da página ser publicada.`],
 'hooks':['Gerador de ganchos',[['Tema','topic'],['Público','aud']],v=>['Antes de gastar dinheiro com isso, veja este passo.','O erro que deixa muita gente ocupada e sem resultado.','Se você é [PÚBLICO], responda esta pergunta.','Três sinais de que sua ideia ainda não está validada.','Você não precisa de mais ferramentas; precisa desta decisão.','O que ninguém registra antes de criar um produto.','Faça este teste em sete minutos.','Pare de medir somente curtidas.','A diferença entre parecer pronto e estar validado.','Salve este checklist antes de começar.'].map((x,i)=>`${i+1}. ${x.replace('[PÚBLICO]',v.aud)} Tema: ${v.topic}`).join('\n')],
 'carousel':['Criador de carrossel',[['Tema','topic'],['Público','aud'],['CTA','cta']],v=>`TELA 1 — Gancho forte sobre ${v.topic}\nTELA 2 — O problema vivido por ${v.aud}\nTELA 3 — Por que a abordagem comum falha\nTELA 4 — Passo prático 1\nTELA 5 — Passo prático 2\nTELA 6 — Erro ou cuidado importante\nTELA 7 — ${v.cta}\n\nUse pouco texto, contraste alto e uma ideia por tela.`],
 'ad':['Criador de anúncio',[['Produto','product'],['Público','aud'],['Benefício realista','benefit'],['CTA','cta']],v=>`${v.aud}, você perde tempo tentando organizar tudo sozinho?\n\nConheça ${v.product}: uma solução prática para ${v.benefit}. Veja os materiais reais, entenda como funciona e escolha o plano que combina com seu momento.\n\n${v.cta}.\n\nSem promessa de resultado: aplicação e contexto fazem diferença.`],
 'email':['E-mail de divulgação',[['Produto','product'],['Público','aud'],['Problema','prob'],['Link/CTA','cta']],v=>`ASSUNTO: Uma forma prática de organizar ${v.prob}\nPRÉVIA: veja os arquivos e entenda se servem para você.\n\nOlá!\nSe você trabalha com ${v.aud} e enfrenta ${v.prob}, o ${v.product} reúne orientações e ferramentas para transformar essa tarefa em um processo mais claro.\n\nVocê pode ver exatamente o que está incluído antes de decidir. O material exige personalização e não promete resultado financeiro.\n\n${v.cta}\n\nSe não quiser receber novas mensagens, responda solicitando a remoção.`],
 'whatsapp':['Mensagem para WhatsApp',[['Situação','situation'],['Nome','name'],['Objetivo','goal']],v=>`Olá, ${v.name || '[NOME]'}. Estou entrando em contato sobre ${v.situation}. Meu objetivo é ${v.goal}. Posso enviar uma explicação curta com escopo, prazo e limites? Se não for prioridade agora, sem problema — encerro por aqui.`],
 'proposal':['Proposta comercial',[['Cliente','client'],['Objetivo','goal'],['Escopo','scope'],['Prazo e valor','terms']],v=>`PROPOSTA COMERCIAL\nCliente: ${v.client}\nObjetivo verificável: ${v.goal}\nEscopo: ${v.scope}\nNão incluído: [LIMITES]\nEtapas e datas: ${v.terms}\nMateriais do cliente: [ITENS]\nRevisões: [QUANTIDADE]\nCritério de aceite: [COMO SERÁ APROVADO]\nValidade: [DATA]\n\nConfirme aspectos jurídicos e tributários com profissionais habilitados.`],
 'wealth':['Simulador de meta patrimonial',[['Patrimônio atual','current','number'],['Aporte mensal','monthly','number'],['Meta','target','number'],['Prazo em meses','months','number']],v=>{const final=+v.current+(+v.monthly*+v.months);return `Sem considerar rendimento, o valor acumulado por aportes seria ${money(final)}.\nDiferença para a meta: ${money(Math.max(0,+v.target-final))}.\n\nEsta simulação não prevê retorno. Considere inflação, custos, riscos, liquidez e orientação adequada.`}],
 'briefing':['Briefing de cliente',[['Projeto ou serviço','project'],['Objetivo do cliente','goal'],['Público final','aud']],v=>`BRIEFING PARA ${v.project}\n\nObjetivo confirmado: ${v.goal}\nPúblico: ${v.aud}\n\nPerguntas essenciais:\n1. Qual problema precisa ser resolvido?\n2. Qual entrega final será aprovada?\n3. Quais materiais já existem?\n4. O que obrigatoriamente deve aparecer?\n5. O que deve ser evitado?\n6. Quais referências representam o resultado desejado?\n7. Qual prazo real e quem aprova?\n8. Quantas revisões estão previstas?\n9. Em quais canais a entrega será utilizada?\n10. Como o resultado será testado?`],
 'contract':['Roteiro de contrato',[['Serviço contratado','service'],['Escopo combinado','scope'],['Condições de pagamento','payment']],v=>`ROTEIRO PARA REVISÃO PROFISSIONAL\nServiço: ${v.service}\nEscopo: ${v.scope}\nPagamento: ${v.payment}\n\nCláusulas a revisar: identificação das partes; objeto e entregáveis; materiais necessários; cronograma; preço e vencimento; revisões; aceite; propriedade intelectual; confidencialidade e dados; cancelamento; suporte; responsabilidades e solução de conflitos.\n\nEste roteiro não substitui um contrato revisado por profissional habilitado.`],
 'debt':['Mapa de dívidas',[['Descrição da dívida','debt'],['Impacto atual','impact'],['Capacidade de pagamento','capacity']],v=>`MAPA DA DÍVIDA\nSituação: ${v.debt}\nImpacto: ${v.impact}\nCapacidade informada: ${v.capacity}\n\nOrganize credor, saldo, juros, vencimento, atraso, garantia e consequência. Priorize primeiro despesas essenciais e dívidas com maior risco imediato; depois compare custo efetivo e possibilidades oficiais de negociação. Não assuma nova dívida sem calcular o custo total.`],
 'delegate':['Delegação e briefing',[['Tarefa a delegar','task'],['Resultado esperado','result'],['Recursos disponíveis','resources']],v=>`INSTRUÇÃO DE DELEGAÇÃO\nTarefa: ${v.task}\nResultado verificável: ${v.result}\nRecursos: ${v.resources}\n\nEntrada necessária: materiais, acessos e referências autorizadas.\nEtapas: confirmar entendimento; produzir amostra; revisar; executar; testar; entregar.\nLimites: não alterar escopo sem aprovação.\nAtualizações: informar avanço, dúvida e bloqueio.\nAceite: comparar a entrega com o resultado esperado e registrar correções.`],
 'experiment':['Plano de teste',[['Hipótese','hypothesis'],['Variável testada','variable'],['Métrica principal','metric']],v=>`PLANO DE TESTE\nHipótese: ${v.hypothesis}\nÚnica variável alterada: ${v.variable}\nMétrica: ${v.metric}\n\nMantenha público, período, canal, orçamento e oferta comparáveis. Defina versão A, versão B, duração e quantidade mínima de observações antes de começar. Registre resultado bruto, limitações e fatores externos. Não declare vencedor com poucos dados.`],
 'faq':['FAQ e objeções',[['Produto ou serviço','product'],['Dúvida principal','question'],['Resposta verdadeira','answer']],v=>`FAQ DE ${v.product}\n\nPERGUNTA: ${v.question}\nRESPOSTA: ${v.answer}\n\nComplemento recomendado: explique quando a resposta se aplica, quais limitações existem, o que está incluído, o que não está incluído e qual é o próximo passo. Não esconda preço, prazo, compatibilidade, esforço necessário ou política de suporte.`],
 'funnel-diagnosis':['Diagnóstico de funil',[['Etapa com maior perda','stage'],['Comportamento observado','behavior'],['Evidência disponível','evidence']],v=>`DIAGNÓSTICO DA ETAPA ${v.stage.toUpperCase()}\nComportamento: ${v.behavior}\nEvidência: ${v.evidence}\n\nHipóteses a testar: mensagem pouco clara; público inadequado; demora; falta de demonstração; preço sem contexto; dificuldade no checkout. Escolha uma hipótese, altere uma variável e acompanhe taxa de avanço, tempo de resposta e objeções antes de concluir a causa.`],
 'kpis':['Painel de KPIs',[['Objetivo do negócio','goal'],['Canal principal','channel'],['Decisão necessária','decision']],v=>`PAINEL PARA ${v.goal}\nCanal: ${v.channel}\nDecisão: ${v.decision}\n\n1. Pessoas alcançadas qualificadas.\n2. Cliques ou respostas.\n3. Conversas iniciadas.\n4. Propostas ou checkouts iniciados.\n5. Vendas e valor líquido.\n\nRegistre período, origem e fórmula de cada indicador. Use os números para tomar “${v.decision}”, sem confundir visualização com intenção de compra.`],
 'path-assets':['Caminho de organização patrimonial',[['Situação financeira','situation'],['Objetivo e prazo','goal'],['Principal limitação','limit']],v=>`CAMINHO: ORGANIZAÇÃO FINANCEIRA\nSituação: ${v.situation}\nObjetivo: ${v.goal}\nLimitação: ${v.limit}\n\nPrimeiro registre entradas, despesas, dívidas e reserva. Depois defina uma meta compatível com o prazo e compare cenários sem retorno garantido. Próxima evidência: fechamento financeiro de sete dias com saldo conciliado e uma decisão documentada.`],
 'path-product':['Caminho de produtos',[['Conhecimento disponível','knowledge'],['Problema do público','problem'],['Formato possível','format']],v=>`CAMINHO: PRODUTO DIGITAL\nConhecimento: ${v.knowledge}\nProblema: ${v.problem}\nFormato: ${v.format}\n\nCrie uma entrega mínima com instrução, exemplo preenchido, arquivo utilizável e checklist. Mostre a estrutura a pessoas do público antes de ampliar. Próxima evidência: uma amostra aberta e uma lista de dúvidas reais.`],
 'path-service':['Caminho de serviços',[['Habilidade disponível','skill'],['Cliente possível','client'],['Problema observado','problem']],v=>`CAMINHO: SERVIÇO\nHabilidade: ${v.skill}\nCliente: ${v.client}\nProblema: ${v.problem}\n\nTransforme a habilidade em uma entrega pequena com escopo, prazo e limite de revisões. Prepare uma demonstração relacionada ao problema e peça opinião sem prometer resultado. Próxima evidência: amostra concluída e reação registrada.`],
 'process-audit':['Auditoria de processo',[['Processo analisado','process'],['Falha observada','failure'],['Consequência da falha','impact']],v=>`AUDITORIA DE ${v.process}\nFalha: ${v.failure}\nConsequência: ${v.impact}\n\nMapeie entrada, responsável, etapas, espera, retrabalho e saída. Localize onde a falha começa, não apenas onde aparece. Meça frequência, tempo perdido e impacto. Corrija um ponto, execute novamente e compare antes/depois com a mesma condição.`],
 'reserve':['Reserva financeira',[['Despesas essenciais mensais','expense','number'],['Meses desejados','months','number'],['Valor já reservado','current','number']],v=>{const target=+v.expense*+v.months,gap=Math.max(0,target-(+v.current));return `META DE RESERVA: ${money(target)}\nValor atual: ${money(v.current)}\nDiferença: ${money(gap)}\n\nA quantidade de meses depende de estabilidade, responsabilidades e acesso a renda. Mantenha liquidez e segurança compatíveis com a finalidade; confirme decisões financeiras importantes com profissional adequado.`}],
 'scenarios':['Comparador de cenários',[['Decisão analisada','decision'],['Cenário mínimo','minimum'],['Cenário esperado','base'],['Cenário máximo responsável','maximum']],v=>`DECISÃO: ${v.decision}\n\nMÍNIMO: ${v.minimum}\nBASE: ${v.base}\nMÁXIMO RESPONSÁVEL: ${v.maximum}\n\nCompare custo, prazo, capacidade, risco e consequência de cada cenário. Escolha o cenário que continua viável caso a procura seja menor ou o custo aumente. Registre o sinal que exigirá revisão da decisão.`],
 'sop':['Procedimento operacional',[['Nome do processo','process'],['Entrada necessária','input'],['Resultado final','output']],v=>`PROCEDIMENTO: ${v.process}\nEntrada: ${v.input}\nSaída verificável: ${v.output}\n\n1. Confirmar entrada e responsável.\n2. Validar formato e informações.\n3. Executar a primeira etapa e registrar evidência.\n4. Realizar conferência intermediária.\n5. Corrigir divergências.\n6. Produzir a saída final.\n7. Testar conforme o critério de aceite.\n8. Arquivar versão, data e responsável.\n\nRiscos: entrada incompleta, versão errada, prazo sem responsável e ausência de teste.`]
};
function toolModal(id){if(id==='backup')return download('ontop-backup.json',JSON.stringify(data,null,2),'application/json');if(id.endsWith('-csv'))return exportBy(id);if(id==='restore')return restore();if(id==='favorites'){return showModal('Favoritos',data.favorites.map(x=>`<div class="result">${esc(x)}</div>`).join('')||'<p>Nenhum favorito.</p>')}if(id==='calendar')return calendarTool();if(id==='compare')return compareTool();if(id==='pdf')return pdfTool();if(id==='quality')return showModal('Checklist de qualidade',`<div class="list">${['Tudo anunciado existe','PDFs e planilhas abrem','Links foram testados','Instruções estão claras','Contagens foram conferidas','Não há números ou depoimentos inventados','Limites e esforço estão visíveis','Compatibilidade foi testada no celular','Preço, acesso e suporte estão corretos','Uma pessoa independente revisou'].map(x=>`<label class="list-item"><input type="checkbox"><span>${x}</span></label>`).join('')}</div>`);const gen=generators[id];if(!gen)return toast('Ferramenta sem configuração específica.');showGeneratorAI(gen)}
function showGenerator([title,fields,fn]){showModal(title,`<p class="input-rule">Preencha cada resposta descritiva com no mínimo 10 letras. A resposta será construída somente com o contexto informado.</p><div class="form-grid">${fields.map(([label,id,type])=>`<div class="field"><label>${label}</label><input id="m-${id}" type="${type||'text'}" ${type==='number'?'min="0" step="any"':'minlength="10"'}></div>`).join('')}</div><div class="action-row"><button class="primary" id="m-generate" disabled>Gerar resposta personalizada</button><button class="secondary" id="m-copy">Copiar</button><button class="secondary" id="m-save">Salvar</button></div><div class="result" id="m-result">Aguardando respostas completas.</div>`);const generate=$('#m-generate'),result=$('#m-result'),ready=()=>fields.every(([,id,type])=>type==='number'?$('#m-'+id).value!==''&&+$(`#m-${id}`).value>=0:letterCount($(`#m-${id}`).value)>=10);fields.forEach(([,id])=>$(`#m-${id}`).oninput=()=>generate.disabled=!ready());generate.onclick=()=>{const textFields=fields.filter(([,id,type])=>type!=='number').map(([label,id])=>[$(`#m-${id}`),label]);if(!requireLetters(textFields))return;const missingNumber=fields.find(([,id,type])=>type==='number'&&(!Number.isFinite(+$(`#m-${id}`).value)||+$(`#m-${id}`).value<0));if(missingNumber){$(`#m-${missingNumber[1]}`).focus();return toast(`${missingNumber[0]} precisa de um número válido.`)}const v=Object.fromEntries(fields.map(([,id])=>[id,$(`#m-${id}`).value.trim()]));result.textContent=fn(v)};$('#m-copy').onclick=()=>{if(result.textContent==='Aguardando respostas completas.')return toast('Gere uma resposta antes de copiar.');copy(result.textContent)};$('#m-save').onclick=()=>{if(result.textContent==='Aguardando respostas completas.')return toast('Gere uma resposta antes de salvar.');data.favorites.unshift(result.textContent);save();toast('Salvo nos favoritos')}}
function showModal(title,body){const el=document.createElement('div');el.className='modal';el.innerHTML=`<div class="modal-box"><div style="display:flex;justify-content:space-between;gap:15px"><h2>${title}</h2><button class="secondary" data-close>Fechar</button></div>${body}</div>`;document.body.append(el);el.onclick=e=>{if(e.target===el||e.target.closest('[data-close]'))el.remove()}}
function showGeneratorAI([title,fields]){showModal(title,`<p class="input-rule">Preencha cada resposta descritiva com no mínimo 10 letras. A IA criará uma resposta nova usando o contexto informado. Limite: 20 respostas por dia.</p><div class="form-grid">${fields.map(([label,id,type])=>`<div class="field"><label>${label}</label><input id="m-${id}" type="${type||'text'}" ${type==='number'?'min="0" step="any"':'minlength="10"'}></div>`).join('')}</div><div class="action-row"><button class="primary" id="m-generate" disabled>Gerar com inteligência artificial</button><button class="secondary" id="m-copy">Copiar</button><button class="secondary" id="m-save">Salvar</button></div><div class="result" id="m-result">Aguardando respostas completas.</div>`);const generate=$('#m-generate'),result=$('#m-result'),ready=()=>fields.every(([,id,type])=>type==='number'?$('#m-'+id).value!==''&&+$(`#m-${id}`).value>=0:letterCount($(`#m-${id}`).value)>=10);fields.forEach(([,id])=>$(`#m-${id}`).oninput=()=>generate.disabled=!ready());generate.onclick=async()=>{const textFields=fields.filter(([,id,type])=>type!=='number').map(([label,id])=>[$(`#m-${id}`),label]);if(!requireLetters(textFields))return;const missingNumber=fields.find(([,id,type])=>type==='number'&&(!Number.isFinite(+$(`#m-${id}`).value)||+$(`#m-${id}`).value<0));if(missingNumber){$(`#m-${missingNumber[1]}`).focus();return toast(`${missingNumber[0]} precisa de um número válido.`)}const payload=fields.map(([label,id,type])=>({label,value:$(`#m-${id}`).value.trim(),type:type||'text'}));generate.disabled=true;generate.textContent='Gerando resposta...';result.textContent='A inteligência artificial está analisando suas respostas.';try{const response=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:localStorage.getItem('ontop-session'),title,fields:payload})});const body=await response.json();if(!response.ok)throw new Error(body.error||'Não foi possível gerar.');result.textContent=body.answer;toast(`Resposta gerada • ${body.remaining} restantes hoje`)}catch(error){result.textContent=`Não foi possível gerar: ${error.message}`}finally{generate.textContent='Gerar novamente com IA';generate.disabled=!ready()}};$('#m-copy').onclick=()=>{if(!result.textContent||result.textContent.startsWith('Aguardando')||result.textContent.startsWith('A inteligência')||result.textContent.startsWith('Não foi possível'))return toast('Gere uma resposta antes de copiar.');copy(result.textContent)};$('#m-save').onclick=()=>{if(!result.textContent||result.textContent.startsWith('Aguardando')||result.textContent.startsWith('A inteligência')||result.textContent.startsWith('Não foi possível'))return toast('Gere uma resposta antes de salvar.');data.favorites.unshift(result.textContent);save();toast('Salvo nos favoritos')}}
function calendarTool(){showModal('Calendário de conteúdo',`<p>Informe o assunto com pelo menos 10 letras e escolha a duração.</p><div class="field"><label>Assunto, produto ou público</label><input id="cal-context" minlength="10" placeholder="Ex.: criação de produtos digitais para iniciantes"></div><div class="action-row"><button class="primary" id="cal30" disabled>Gerar 30 dias</button><button class="secondary" id="cal90" disabled>Gerar 90 dias</button></div><div class="result" id="cal-result">Aguardando um assunto completo.</div>`);const input=$('#cal-context'),b30=$('#cal30'),b90=$('#cal90');input.oninput=()=>{const blocked=letterCount(input.value)<10;b30.disabled=blocked;b90.disabled=blocked};const gen=n=>{if(!requireLetters([[input,'Assunto, produto ou público']]))return;const context=input.value.trim(),arr=Array.from({length:n},(_,i)=>`Dia ${i+1} — ${['Descoberta','Educação','Bastidor','Oferta','Relacionamento'][i%5]} sobre ${context}: ${['erro e correção','passo a passo','demonstração','objeção','pergunta ao público','checklist','comparação'][i%7]}. CTA: ${['comente','salve','compartilhe','veja a demonstração'][i%4]}.`);$('#cal-result').textContent=arr.join('\n')};b30.onclick=()=>gen(30);b90.onclick=()=>gen(90)}
