function pdfTool(){showModal('Gerador de PDF',`<p class="input-rule">Crie um material baixável com a IA Gemini. O conteúdo é desenvolvido em capítulos, com exemplos e aplicação prática; a geração pode levar alguns segundos.</p><div class="form-grid"><div class="field full"><label for="pdf-title">Título do material</label><input id="pdf-title" minlength="3" placeholder="Ex.: Guia para conseguir os primeiros clientes"></div><div class="field"><label for="pdf-audience">Para quem é?</label><input id="pdf-audience" minlength="3" placeholder="Ex.: autônomos iniciantes"></div><div class="field"><label for="pdf-tone">Tom de voz</label><select id="pdf-tone"><option>Prático e acolhedor</option><option>Direto e profissional</option><option>Leve e inspirador</option><option>Didático e técnico</option></select></div><div class="field full"><label for="pdf-instruction">O que o material deve ensinar?</label><textarea id="pdf-instruction" rows="4" minlength="10" placeholder="Descreva o conteúdo, o objetivo e os pontos que não podem faltar."></textarea></div></div><div class="action-row"><button class="primary" id="pdf-generate" disabled>Gerar PDF detalhado</button></div><div class="result" id="pdf-result">Preencha os campos para começar.</div>`);const title=$('#pdf-title'),audience=$('#pdf-audience'),instruction=$('#pdf-instruction'),generate=$('#pdf-generate'),result=$('#pdf-result'),ready=()=>letterCount(title.value)>=3&&letterCount(audience.value)>=3&&letterCount(instruction.value)>=10;[title,audience,instruction].forEach(field=>field.oninput=()=>{generate.disabled=!ready();result.textContent=ready()?'Pronto para criar o material detalhado.':'Preencha título, público e instruções.'});generate.onclick=async()=>{if(!ready())return;generate.disabled=true;generate.textContent='Gemini está escrevendo...';result.textContent='A Gemini está desenvolvendo capítulos, exemplos e checklist. Aguarde; não feche esta janela.';try{const aiResponse=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:localStorage.getItem('ontop-session'),title:'Gerador de PDF',fields:[{label:'Título',value:title.value.trim(),type:'text'},{label:'Público',value:audience.value.trim(),type:'text'},{label:'Instruções',value:instruction.value.trim(),type:'text'}]})}),aiBody=await aiResponse.json();if(!aiResponse.ok)throw new Error(aiBody.error||'A Gemini não conseguiu criar o conteúdo.');const answer=String(aiBody.answer||'');const chars=answer.replace(/\s/g,'').length;if(chars<9000)throw new Error('A Gemini devolveu um texto incompleto. O PDF não foi baixado; tente novamente.');result.textContent=`Conteúdo concluído (${answer.split(/\s+/).filter(Boolean).length} palavras). Montando páginas...`;generate.textContent='Montando PDF...';const pdfResponse=await fetch('/api/ebook-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:localStorage.getItem('ontop-session'),title:title.value.trim(),audience:audience.value.trim(),tone:$('#pdf-tone').value,template:'guia',content:answer})});if(!pdfResponse.ok){const body=await pdfResponse.json().catch(()=>({}));throw new Error(body.error||'Não foi possível montar o PDF.')}const blob=await pdfResponse.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`${title.value.trim().replace(/[^a-zA-Z0-9À-ÿ]+/g,'-').replace(/^-|-$/g,'')||'ontop-material'}.pdf`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);result.textContent='PDF detalhado criado e baixado com sucesso.';toast(`PDF pronto • ${aiBody.remaining??'1'} respostas restantes hoje`)}catch(error){result.textContent=`Não foi possível gerar: ${error.message}`}finally{generate.textContent='Gerar PDF detalhado';generate.disabled=!ready()}}}
