 document.querySelectorAll('[data-page]').forEach(b=>{const go=()=>{state.page=b.dataset.page;$('#sidebar').classList.remove('open');layout()};b.onclick=go;if(b.tagName!=='BUTTON'){b.tabIndex=0;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')go()}}});document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>toolModal(b.dataset.tool));
