  '#add-project':()=>{const name=$('#project-name'),next=$('#project-next');if(!requireLetters([[name,'Projeto'],[next,'Próxima ação']]))return;data.projects.push({name:name.value.trim(),date:$('#project-date').value,next:next.value.trim()});save();layout()},
