async function aiStatus(){try{const response=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:localStorage.getItem('ontop-session'),mode:'status'})});const body=await response.json();if(response.ok){if($('#ai-remaining'))$('#ai-remaining').textContent=body.remaining;if($('#profile-remaining'))$('#profile-remaining').textContent=`${body.remaining} de ${body.limit||20} respostas`}}catch{}}
function bindAIChat(){document.querySelectorAll('[data-quick-prompt]').forEach(button=>button.onclick=()=>{const input=$('#ai-chat-input');if(input){input.value=button.dataset.quickPrompt;input.dispatchEvent(new Event('input'));input.focus()}});const niche=$('#ai-niche');if(niche)niche.onchange=()=>{data.settings.niche=niche.value;save();toast('Modo da IA atualizado')};const form=$('#ai-chat-form'),input=$('#ai-chat-input'),send=$('#ai-chat-send'),messages=$('#chat-messages');if(!form)return;aiStatus();messages.scrollTop=messages.scrollHeight;messages.onclick=event=>{const button=event.target.closest('[data-copy-answer]');if(button){const message=data.chat[Number(button.dataset.copyAnswer)];if(message?.role==='assistant')copy(cleanAIText(message.text));const saveButton=event.target.closest('[data-save-answer]');if(saveButton){const answer=data.chat[Number(saveButton.dataset.saveAnswer)];if(answer?.role==='assistant'){if(!Array.isArray(data.answerFavorites))data.answerFavorites=[];data.answerFavorites=[{text:cleanAIText(answer.text),date:new Date().toISOString()},...data.answerFavorites].slice(0,30);save();toast('Resposta salva no seu perfil')}}}};input.oninput=()=>{send.disabled=letterCount(input.value)<10;$('#ai-chat-help').textContent=letterCount(input.value)<10?`Faltam ${10-letterCount(input.value)} letras`:'Pronto para enviar'};form.onsubmit=async event=>{event.preventDefault();if(letterCount(input.value)<10)return;const question=input.value.trim(),history=(data.chat||[]).slice(-8);data.chat=[...(data.chat||[]),{role:'user',text:question,date:new Date().toISOString()}].slice(-60);save();messages.innerHTML=renderChatMessages()+`<div class="chat-message assistant waiting"><img class="ontop-chat-mark" src="/assets-ontop-mark.svg?v=2" alt="OnTop"><p>Analisando...</p></div>`;input.value='';send.disabled=true;messages.scrollTop=messages.scrollHeight;try{const response=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:localStorage.getItem('ontop-session'),title:'Chat IA OnTop',fields:[{label:'Pergunta do usuário',value:question,type:'text'}],niche:data.settings.niche||'Negócios e produtos digitais',history})});const body=await response.json();if(!response.ok)throw new Error(body.error||'Não foi possível responder.');data.chat=[...data.chat,{role:'assistant',text:cleanAIText(body.answer),date:new Date().toISOString()}].slice(-60);save();messages.innerHTML=renderChatMessages();$('#ai-remaining').textContent=body.remaining;messages.scrollTop=messages.scrollHeight}catch(error){messages.querySelector('.waiting')?.remove();messages.insertAdjacentHTML('beforeend',`<div class="chat-message assistant error-message"><img class="ontop-chat-mark" src="/assets-ontop-mark.svg?v=2" alt="OnTop"><p>${esc(error.message)}</p></div>`);aiStatus()}}}
function bindChatTools(){const file=$('#chat-file');$('#chat-export').onclick=()=>download('ontop-conversa.json',JSON.stringify({version:1,chat:data.chat},null,2),'application/json');$('#chat-import').onclick=()=>file.click();file.onchange=async()=>{try{const parsed=JSON.parse(await file.files[0].text()),chat=Array.isArray(parsed)?parsed:parsed.chat;if(!Array.isArray(chat))throw new Error();data.chat=chat.slice(-60).map(item=>({role:item.role==='assistant'?'assistant':'user',text:String(item.text||'').slice(0,10000),date:item.date||new Date().toISOString()})).filter(item=>item.text);await saveNow();layout();toast('Conversa restaurada')}catch{toast('Arquivo de conversa inválido')}};$('#chat-clear').onclick=async()=>{if(!confirm('Limpar somente esta conversa? As outras conversas continuarão no histórico.'))return;const chatId=data.activeChatId;data.chat=[];data.conversations=data.conversations.filter(item=>item.id!==chatId);localStorage.setItem(KEY,JSON.stringify(data));try{await fetch('/api/user-data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'clear-chat',chatId,session:localStorage.getItem('ontop-session')})})}catch{}layout();toast('Conversa atual limpa')}}
function bindConversationHistory(){$('#new-chat').onclick=async()=>{await saveNow();data.activeChatId=`chat-${Date.now()}`;data.chat=[];localStorage.setItem(KEY,JSON.stringify(data));await syncCloud();layout();setTimeout(()=>$('#ai-chat-input')?.focus(),50)};document.querySelectorAll('[data-chat-id]').forEach(button=>button.onclick=async()=>{await saveNow();const thread=data.conversations.find(item=>item.id===button.dataset.chatId);if(!thread)return;data.activeChatId=thread.id;data.chat=structuredClone(thread.chat||[]);localStorage.setItem(KEY,JSON.stringify(data));await syncCloud();layout()})}
function bindCopies(){document.querySelectorAll('[data-copy-text]').forEach(b=>b.onclick=()=>copy(b.dataset.copyText))}
function diagnose(){const n=$('#need').value.toLowerCase(),r=$('#resource').value.toLowerCase();let path=n.includes('organ')||n.includes('finan')?'Patrimônio':n.includes('escala')||n.includes('produto')?'Produtos':'Serviços';if(r.includes('conhecimento'))path='Produtos';data.profile.path=path;save();return `CAMINHO PRIORITÁRIO: ${path}\n\nFoco de 30 dias: ${$('#problem').value||'definir um problema específico'}\nTempo disponível: ${$('#hours').value||5} horas por semana.\n\nPróximo passo: conclua uma evidência pequena em sete dias e revise antes de ampliar. Mantenha os outros caminhos como apoio.`}
function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Arquivo gerado')}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n')}
function exportBy(id){if(id==='clients-csv')download('ontop-clientes.csv',csv([['Cliente','Contato','Produto','Etapa'],...data.clients.map(x=>[x.name,x.contact,x.product,x.stage])]),'text/csv');if(id==='finance-csv')download('ontop-financeiro.csv',csv([['Data','Descrição','Tipo','Categoria','Valor'],...data.finance.map(x=>[x.date,x.desc,x.type,x.category,x.value])]),'text/csv');if(id==='progress-csv')download('ontop-progresso-90-dias.csv',csv([['Dia','Fase','Tarefa','Concluído'],...days90.map(x=>[x.day,x.phase,x.task,data.tasks[x.day]?'Sim':'Não'])]),'text/csv')}
function generateCertificate(){const name=prompt('Digite seu nome completo para o certificado:');if(!name)return;const issued=new Date().toLocaleDateString('pt-BR');const win=open('','_blank');if(!win)return toast('Permita pop-ups para gerar o certificado.');win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Certificado OnTop</title><style>@page{size:A4 landscape;margin:0}*{box-sizing:border-box}body{margin:0;background:#070707;color:#fff;font-family:Arial,sans-serif}.sheet{width:297mm;height:210mm;padding:18mm;border:7mm solid #d7a72b;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}.brand{letter-spacing:8px;color:#f2c14e;font-size:25px;font-weight:900}.title{font-size:52px;margin:22px 0 8px}.name{font-size:42px;color:#f2c14e;border-bottom:2px solid #f2c14e;padding:10px 42px}.copy{max-width:850px;font-size:20px;line-height:1.6}.foot{margin-top:34px;color:#bbb}@media print{button{display:none}}</style></head><body><div class="sheet"><div class="brand">ONTOP</div><div class="title">Certificado de conclusão</div><p class="copy">Certificamos que</p><div class="name">${esc(name)}</div><p class="copy">concluiu a Jornada OnTop de 90 dias, dedicada ao planejamento, validação de ofertas, organização comercial e gestão responsável. Este certificado comprova participação e conclusão do conteúdo; não representa promessa de renda ou resultado financeiro.</p><div class="foot">Emitido em ${issued} • OnTop Central Plus</div><button onclick="print()">Baixar / imprimir em PDF</button></div></body></html>`);win.document.close()}
function restore(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const parsed=JSON.parse(await input.files[0].text());data={...structuredClone(defaults),...parsed};save();layout();toast('Backup restaurado')}catch{toast('Arquivo de backup inválido')}};input.click()}
async function copy(t){await navigator.clipboard.writeText(t);toast('Copiado')}

async function login(value){if(['localhost','127.0.0.1'].includes(location.hostname)&&value==='ONTOP-PREVIEW'){state.access={name:'Membro Plus',status:'active'};return showApp()}const isSession=String(value).startsWith('OTS_'),res=await fetch('/api/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(isSession?{session:value}:{code:value})}),body=await res.json();if(!res.ok)throw new Error(body.error||'Falha no acesso');localStorage.setItem('ontop-session',body.session);state.access=body.access;await loadCloud();showApp()}
function showOnboarding(){showModal('Bem-vindo à OnTop',`<div class="onboarding onboarding-rich"><p class="eyebrow">SUA CENTRAL DE EXECUÇÃO</p><h3>Decida melhor e avance com clareza.</h3><p>Você tem um espaço para conversar com a IA, organizar projetos, seguir uma jornada e criar materiais visuais.</p><div class="onboarding-points"><div><b>01</b><span><strong>Clareie</strong><small>Use a IA com um modo adequado ao seu objetivo.</small></span></div><div><b>02</b><span><strong>Execute</strong><small>Transforme ideias em tarefas pequenas e verificáveis.</small></span></div><div><b>03</b><span><strong>Revise</strong><small>Salve respostas e referências para reutilizar depois.</small></span></div></div><p>Você tem até 20 respostas da IA por dia. Suas conversas e progresso ficam sincronizados.</p><button class="primary" id="finish-onboarding">Explorar a Central</button></div>`);$('#finish-onboarding').onclick=()=>{data.settings={...defaults.settings,...data.settings,onboarded:true};save();document.querySelector('.modal')?.remove()}}
function showApp(){data.settings={...defaults.settings,...data.settings};$('#gate').classList.add('hidden');$('#app').classList.remove('hidden');$('#avatar').textContent=(state.access?.name||'Plus').charAt(0).toUpperCase();layout();if(!data.settings.onboarded)setTimeout(showOnboarding,150)}
$('#access-form').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button');btn.disabled=true;$('#access-error').textContent='';try{await login($('#access-code').value)}catch(err){$('#access-error').textContent=err.message}finally{btn.disabled=false}};
$('#logout').onclick=()=>{localStorage.removeItem('ontop-session');location.reload()};$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#close-menu').onclick=()=>$('#sidebar').classList.remove('open');
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferred=e;$('#install').style.display='block'});$('#install').onclick=async()=>{if(state.deferred){state.deferred.prompt();state.deferred=null}else toast('Use “Adicionar à tela inicial” no menu do navegador')};
document.addEventListener('click',event=>{if(event.target.closest('#home-learning,#open-learning-home'))document.querySelector('.guide-nav-home')?.click();if(event.target.closest('#home-ai'))document.querySelector('#academy-link')?.click()});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js?v=28').then(registration=>registration.update()).catch(()=>{});
const session=localStorage.getItem('ontop-session');if(session)login(session).catch(()=>localStorage.removeItem('ontop-session'));
const pdfHomeButton=document.createElement('button');pdfHomeButton.className='ghost pdf-home-action';pdfHomeButton.type='button';pdfHomeButton.textContent='PDF com IA';pdfHomeButton.setAttribute('aria-label','Abrir PDF com IA');pdfHomeButton.onclick=()=>pdfTool();document.querySelector('.top-actions')?.prepend(pdfHomeButton);
